utton{display:block;margin:14rpx 0 0;font-size:23rpx}.coupon-empty{padding:20rpx 0;text-align:center;color:#888;font-size:23rpx;line-height:1.7}.coupon-more,.coupon-wallet{margin:18rpx 0;font-size:24rpx!important;background:#fff8f5;color:#984d3d}.coupon-wallet{background:transparent}@media(min-width:768px){.coupon-benefit{flex-basis:170px}.coupon-benefit>text{font-size:32px}.coupon-heading{font-size:20px}.coupon-meta,.coupon-scope{font-size:15px}.coupon-rules{font-size:16px}}
